function quizModal(){let q=ui.quiz,step=q.step,body;if(step<0){body=`<div class="modal-head"><div><div class="eyebrow">CLASSIC CHARACTER MATCH</div><h2>캐릭터를 만들기 전에,<br>고전 속 나를 먼저 만나 볼까요?</h2><p>${esc(ui.nickname||state.nickname)}님이 이야기의 주인공이라면 어떤 선택을 할까요? 5가지 상황에서 마음이 가는 대사를 골라 주세요. 닮은 고전 문학 인물이 내 캐릭터가 돼요.</p></div>${quizClose()}</div><div class="quiz-cast">${characters.map(c=>`<div>${avatar([0,0,0,0,0,0,0],'cast-avatar',c.id)}<span>${esc(c.name)}</span></div>`).join('')}</div><div class="quiz-start"><button class="primary" data-action="quiz-begin" data-autofocus>설문 시작하기 <span>→</span></button><small>5문항 · 약 1분 · 정답은 없어요</small></div>`}else{let item=questions[step];body=`<div class="modal-head"><div><div class="eyebrow">CLASSIC CHARACTER MATCH · ${esc(item.tag)}</div><h2>${esc(item.title)}</h2></div>${quizClose()}</div><div class="quiz-progress" aria-label="${step+1}번째 질문 / 5"><span>${step+1} / 5</span><div class="quiz-rail"><i style="width:${(step+1)*20}%"></i></div></div><p class="quiz-scene">${esc(item.scene)}</p><div class="quiz-answers">${item.choices.map((c,i)=>`<button class="quiz-answer ${q.choices[step]===i?'selected':''}" data-action="quiz-answer" data-opt="${i}" ${i===0?'data-autofocus':''}><span class="quiz-letter">${i?'B':'A'}</span><span><strong>${esc(c.text)}</strong><small>${esc(c.sub)}</small></span></button>`).join('')}</div><div class="quiz-bottom"><button class="text-btn" data-action="quiz-back">← ${step?'이전 질문':'처음으로'}</button><small>키보드 1, 2로도 고를 수 있어요</small></div>`}return `<div class="overlay quiz-overlay" role="presentation"><div class="modal-shell quiz-shell" role="dialog" aria-modal="true" aria-label="고전 문학 인물 유형 설문"><div class="standard-modal quiz-modal">${body}</div></div></div>`}
const quizClose=()=>`<button class="icon-btn close" data-action="quiz-close" aria-label="설문 닫기">×</button>`;
function matchModal(){let m=ui.match,c=m.ranked.find(x=>x.id===m.selected),best=m.ranked[0],name=ui.nickname||state.nickname;return `<div class="overlay quiz-overlay" role="presentation"><div class="modal-shell match-shell" role="dialog" aria-modal="true" aria-label="설문 결과"><div class="standard-modal match-modal"><div class="modal-head"><div><div class="eyebrow">${c.id===best.id?'YOUR LITERARY ALTER EGO':'ALSO SIMILAR'} · 일치 ${c.score}/5</div><h2>${esc(name)}님은<br><em>${esc(withGwa(c.name))}</em> 닮았어요</h2><p>『${esc(c.book)}』 — ${esc(c.author)}</p></div>${quizClose()}</div><div class="match-layout"><div class="pixel-card"><div class="pixel-card-stage">${avatar([0,0,0,0,0,0,0],'match-avatar',c.id)}</div><b>${esc(c.name)}</b><span>${esc(c.title)}</span></div><div class="match-copy"><div class="match-type">${esc(c.type)}</div><p>${esc(c.intro)}</p><blockquote>${esc(c.line)}</blockquote><div class="match-details"><div><b>✦ 빛나는 강점</b><p>${esc(c.strength)}</p></div><div><b>↗ 성장의 힌트</b><p>${esc(c.growth)}</p></div></div><div class="match-why"><b>닮은 이유 · 일치 ${c.score}/5</b><p>${esc(c.why)}</p></div></div></div><div class="eyebrow match-sub">MATCHED CHARACTERS · 다른 인물로 시작할 수도 있어요</div><div class="match-runners">${m.ranked.slice(0,3).map(p=>`<button class="match-runner ${p.id===c.id?'selected':''}" data-action="match-pick" data-id="${p.id}" aria-pressed="${p.id===c.id}">${avatar([0,0,0,0,0,0,0],'runner-avatar',p.id)}<span><b>${esc(p.name)}</b><small>${esc(p.title)} · 일치 ${p.score}/5</small></span></button>`).join('')}</div><div class="match-actions"><button class="primary" data-action="match-confirm" data-autofocus>${esc(withRo(c.name))} 캐릭터 꾸미기 <span>→</span></button><button class="outline" data-action="quiz-restart">다시 설문하기</button></div><small class="hint">재미를 위한 문학 인물 매칭이며 심리검사가 아닙니다. 인물 대사는 원문 인용이 아닌 창작 문장입니다.</small></div></div></div>`}
function createPage(){let c=characterById(ui.character),opts=optionsFor(c.id);return `<div class="create-page"><header class="simple-header">${logo()}<span>CHARACTER STUDIO &nbsp; / &nbsp; 02</span></header><main class="creator"><div class="creator-intro"><div class="eyebrow">YOUR MAIN CHARACTER</div><h1>나와 닮은 주인공을<br>내 스타일로 꾸며요</h1><p>설문 결과 『${esc(c.book)}』의 ${esc(withGwa(c.name))} 닮았어요.<br>머리색과 옷 색을 바꿔 나만의 캐릭터를 완성해 보세요.</p><div class="preview-stage pixel-stage">${avatar(ui.editor,'big',c.id)}<div class="stage-shadow"></div><small>${esc(ui.nickname)}의 캐릭터 · ${esc(c.title)}</small></div><div class="creator-match"><div><b>${esc(c.name)}</b><span>${esc(c.type)}</span></div><button class="text-btn" data-action="quiz-restart">설문 다시 하기 ↺</button></div></div><div class="creator-controls">${state.nickname?`<label class="edit-nickname">닉네임<input id="edit-nick" maxlength="12" value="${esc(ui.nickname)}" placeholder="닉네임을 입력해 주세요"></label>`:''}<div class="control-heading"><span>CHARACTER CUSTOMIZATION</span><b>01 — ${String(opts.length+1).padStart(2,'0')}</b></div>${opts.map((o,n)=>`<section class="option"><div><b>${o.label}</b><span>${String(n+1).padStart(2,'0')}</span></div><div class="option-row">${o.colors.map(([label,color],j)=>`<button class="option-chip swatch ${(ui.editor[o.slot]||0)===j?'selected':''}" data-action="option" data-i="${o.slot}" data-j="${j}" aria-pressed="${(ui.editor[o.slot]||0)===j}"><i style="background:${color||baseColor(c.id,o.role)}"></i>${label}</button>`).join('')}</div></section>`).join('')}<section class="option"><div><b>${accessoryOption.label}</b><span>${String(opts.length+1).padStart(2,'0')}</span></div><div class="option-row">${accessoryOption.items.map((v,j)=>`<button class="option-chip ${(ui.editor[6]||0)===j?'selected':''}" data-action="option" data-i="6" data-j="${j}" aria-pressed="${(ui.editor[6]||0)===j}">${v}</button>`).join('')}</div></section><button class="primary full" data-action="finish">캐릭터 완성하고 입장하기 <span>→</span></button>${state.nickname?`<div class="edit-shop"><h2>꾸미기 상점</h2>${shop()}</div>`:''}</div></main>${state.nickname?bottomNav():''}${studioFooter()}</div>`}
function openQuiz(from){ui.quizReturn=from;ui.quiz={step:-1,choices:[]};ui.match=null;ui.modal=null;ui.event=false;ui.screen='quiz'}
const welcomePage=()=>`<main class="welcome"><div class="welcome-top">${logo()}${ui.replaying&&ui.screen==='welcome'?`<button class="replay-exit" data-action="replay-exit">도서관으로 돌아가기</button>`:'<span>YOUR STORY, YOUR SPOTLIGHT</span>'}</div><div class="welcome-inner"><div class="welcome-copy"><div class="eyebrow light">A LITTLE WORLD FOR READERS</div><h1>당신의 이야기가<br><em>빛나는 곳.</em></h1><p>책을 펼치는 순간부터 당신은 주인공이에요.<br>나만의 캐릭터와 함께 독서의 즐거움을 발견해 보세요.</p><label for="nick">어떤 이름으로 불러드릴까요?</label><div class="entry"><input id="nick" maxlength="12" placeholder="닉네임을 입력해 주세요" value="${esc(ui.nickname)}"><button data-action="start">시작하기 <span>↗</span></button></div><small>회원가입 없이 시작해요. 기록은 이 브라우저에 저장됩니다.</small></div><div class="welcome-art"><div class="art-frame"><img class="supplied-logo" src="/assets/brand/logo-horizontal.png" alt="Read Carpet 로고"><div class="art-title">Every reader<br>deserves a<br><i>spotlight.</i></div><div class="art-avatar">${avatar([0,0,0,0,0,0,0],'','hong')}</div><div class="art-floor"></div><span class="art-caption">THE READER'S CLUB · EST. 2026</span></div></div></div><footer><span>READ MORE, BE MORE.</span>${studioFooter()}</footer></main>`;
function render(){document.body.append(scrollButton);scrollButton.hidden=true;document.documentElement.dataset.theme=ui.theme; if(['welcome','quiz','result'].includes(ui.screen)){app.innerHTML=welcomePage()+(ui.screen==='quiz'?quizModal():ui.screen==='result'?matchModal():'');focusDialog();return}
if(ui.screen==='create'){app.innerHTML=createPage();return}

app.innerHTML=`<main class="world"><div class="lobby-viewport" aria-label="도서관 지도"><canvas class="library-canvas" aria-hidden="true"></canvas><div class="lobby-player">${avatar()}<span>${esc(state.nickname)}</span></div><div class="lobby-logo">${logo()}</div><button class="lobby-event" data-action="event">이벤트</button><div class="lobby-controls" aria-label="이동"><button data-action="move" data-d="up" aria-label="위로 이동">↑</button><div><button data-action="move" data-d="left" aria-label="왼쪽으로 이동">←</button><button data-action="move" data-d="down" aria-label="아래로 이동">↓</button><button data-action="move" data-d="right" aria-label="오른쪽으로 이동">→</button></div></div></div></main>${ui.modal?modal():''}${ui.event?eventPanel():''}<button class="lobby-event lobby-replay" data-action="replay-onboarding">온보딩 다시 보기</button>${bottomNav()}`;
requestAnimationFrame(()=>{updateWalker();setupCatalog()});
}
function modal(){let content='';if(ui.modal==='home'||ui.modal==='person'){let other=ui.modal==='person',p=people.find(x=>x.id===ui.person),name=other?p.name:state.nickname;content=miniHome(other,p,name)}
else if(ui.modal==='categories'){let filtered=books.filter(b=>(ui.category==='전체'||b.cat===ui.category)&&(`${b.title} ${b.author}`.toLowerCase().includes(ui.search.toLowerCase())));content=`<div class="standard-modal"><div class="modal-head"><div><div class="eyebrow">EXPLORE THE LIBRARY</div><h2>책과 만나는 시간</h2><p>마음이 머무는 서가를 골라 보세요.</p></div>${close()}</div><div class="filter-row"><div class="filter-tabs">${['전체',...cats].map(c=>`<button data-action="filter" data-cat="${c}" class="${ui.category===c?'active':''}">${c}</button>`).join('')}</div><input class="search" placeholder="제목 또는 작가 검색" value="${esc(ui.search)}" aria-label="도서 검색"></div><div class="catalog">${filtered.length?filtered.slice(0,ui.catalogLimit).map(catalogCard).join(''):'<div class="empty">찾는 책이 없어요. 다른 제목이나 작가를 검색해 보세요.</div>'}</div>${filtered.length?`<div class="catalog-more" aria-live="polite">${filtered.length>ui.catalogLimit?'도서를 불러오는 중…':`도서 ${filtered.length}권을 모두 살펴봤어요.`}</div>`:''}</div>`}
else if(ui.modal==='book'){let b=books.find(x=>x.id===ui.book),entry=state.shelf[b.id];content=bookView(b,entry)}
else if(ui.modal==='missions')content=missionsView();
else if(ui.modal==='desk')content=deskView();
else if(ui.modal==='arena-demo')content=arenaView();
else if(ui.modal==='wiki')content=wikiView();
else if(ui.modal==='arena-people')content=`<div class="standard-modal"><div class="modal-head"><div><h2>독서 아레나</h2><p>대결할 독자의 미니홈피를 방문해 보세요.</p></div>${close()}</div><div class="carousel people">${people.slice(0,6).map(personCard).join('')}</div></div>`;
else if(ui.modal==='shop')content=`<div class="standard-modal"><div class="modal-head"><div><div class="eyebrow">LITTLE REWARDS</div><h2>꾸미기 상점</h2><p>모은 숙련도로 나만의 공간을 꾸며요.</p></div>${close()}</div>${shop()}</div>`;
else if(ui.modal==='duel')content=`<div class="standard-modal duel-modal"><div class="modal-head"><div><div class="eyebrow">READ CARPET ARENA</div><h2>독서 아레나</h2><p>${people.find(p=>p.id===ui.person)?.name}님과 대결해요. 책 카드 3장을 골라 주세요.</p></div>${close()}</div><div class="duel-note">예시 상대와의 즉시 대결 · 선택한 책의 숙련도를 비교해요</div><div class="duel-grid">${books.map(b=>`<button data-action="duel-pick" data-id="${b.id}" class="duel-card ${ui.duel.includes(b.id)?'selected':''}">${cover(b)}<b>${b.title}</b><span>시연 숙련도 ${demoMine(b.id)} P</span></button>`).join('')}</div><button class="primary full" data-action="duel-start" ${ui.duel.length!==3?'disabled':''}>${ui.duel.length} / 3 선택 · 대결 시작</button>${ui.result?`<div class="duel-result"><b>${ui.result}</b><p>예시 대결 결과가 로컬에 반영되었어요.</p></div>`:''}</div>`;
return `<div class="overlay" role="presentation"><div class="modal-shell ${ui.modal==='home'||ui.modal==='person'?'home-shell':ui.modal==='missions'?'mission-shell':''}" role="dialog" aria-label="${ui.modal==='book'?'도서 포럼':'상세 화면'}">${content}</div></div>`}

function roomView(other){let p=other?people.find(person=>person.id===ui.person):null;return `<div class="miniroom" aria-label="아이소메트릭 미니룸"><button class="mission-stamp" data-action="mission-overlay" aria-label="오늘의 미션 열기"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M8 5a4 4 0 0 1 8 0c0 2-1 3-2 4v2H10V9C9 8 8 7 8 5ZM7 14h10v3H7zM5 20h14v-3H5z"/></svg></button><img src="/assets/miniroom/isometric-room.svg" alt=""><div class="room-character">${avatar(other?[0,0,0,0,0,0,0]:state.avatar,'',other?p.character:state.character)}</div></div>`}
function styleCategories(){let options=hasSprite(state.character)?optionsFor(state.character):colorOptions;return [...options,{slot:6,label:'머리 장식',colors:accessoryOption.items.map(name=>[name])}]}
function ownsStyle(slot,index){if(index===0)return true;if(slot===6){let oldItem={1:0,3:1,4:2}[index];if(oldItem!==undefined&&state.items.includes(oldItem))return true}return state.styleOwned.includes(`${slot}:${index}`)}
function chooseStyle(el){let slot=+el.dataset.slot,index=+el.dataset.index,option=styleCategories().find(c=>c.slot===slot);if(!option||!option.colors[index])return;if(!ownsStyle(slot,index)){let price=40+index*20;if(state.points<price){alert('사용 가능한 숙련도가 부족해요.');return}state.points-=price;state.styleOwned.push(`${slot}:${index}`)}state.avatar[slot]=index;save()}
function inventoryView(other){if(other)return '<div class="empty">아직 공개된 꾸미기 아이템이 없어요.</div>';let categories=styleCategories(),active=categories.find(c=>c.slot===ui.inventoryCategory)||categories[0];return `<div class="section-head"><div><h3>캐릭터 꾸미기</h3><p class="hint">보유 아이템을 장착하거나 숙련도로 새 아이템을 구매해요.</p></div></div><div class="inventory-preview">${avatar(state.avatar,'',state.character)}<span><b>${esc(state.nickname)}</b><small>사용 가능 ${state.points} P</small></span></div><div class="style-tabs" aria-label="꾸미기 부위">${categories.map(c=>`<button data-action="style-category" data-slot="${c.slot}" class="${c.slot===active.slot?'active':''}" aria-pressed="${c.slot===active.slot}">${esc(c.label)}</button>`).join('')}</div><div class="inventory-grid">${active.colors.map(([name,color],index)=>{let owned=ownsStyle(active.slot,index),selected=(state.avatar[active.slot]||0)===index,price=40+index*20,acc=active.slot===6;return `<div class="inventory-item"><div class="style-swatch ${acc?'style-accessory':''}" style="--swatch:${color||baseColor(state.character,active.role)||'#eee4d8'}">${acc?`<span>${index?['','🎀','▰','✦','✿'][index]:'−'}</span>`:''}</div><b>${esc(name)}</b><span class="style-status">${owned?'보유 중':price+' P'}</span><button class="outline" data-action="style-select" data-slot="${active.slot}" data-index="${index}" ${selected?'disabled':''}>${selected?'장착 중':owned?'장착하기':'구매하기'}</button></div>`}).join('')}</div>`}
function guestbookView(other){let key=other?ui.person:'mine',posts=state.guestbook[key]||[];return `<div class="section-head"><h3>방명록</h3></div><p class="hint">기록은 이 기기에만 저장됩니다.</p><div class="post-form"><input class="guestbook-input" maxlength="200" placeholder="따뜻한 인사를 남겨 주세요" aria-label="방명록 내용"><button data-action="guestbook-add">등록</button></div>${posts.length?posts.map(p=>`<div class="discussion"><b>${esc(p.author)}</b> <small>${esc(p.date)}</small><p>${esc(p.text)}</p></div>`).join(''):'<div class="empty">아직 남겨진 인사가 없어요.</div>'}`}
function friendWave(other,p){const list=people.filter(person=>!other||person.id!==p.id).sort((a,b)=>{const ai=state.visitHistory.indexOf(a.id),bi=state.visitHistory.indexOf(b.id);return (ai<0?999:ai)-(bi<0?999:bi)});return `<section class="friend-wave"><div class="friend-heading"><span>일촌 337명</span></div>${other?`<button class="outline friend-request" data-action="friend-request">${state.friendRequests[p.id]?'일촌 신청 완료':'일촌 신청하기'}</button>`:''}<div class="friend-list">${list.map(person=>`<button data-action="person" data-id="${person.id}"><span>${esc(person.name)}</span></button>`).join('')}</div></section>`}
function miniHome(other,p,name){let recent=other?books.slice(0,2):Object.keys(state.shelf).filter(id=>state.shelf[id].score>0).slice(-3).reverse().map(id=>books.find(b=>b.id==id)).filter(Boolean);if(!recent.length)recent=[books[0]];return `<div class="minihome"><aside class="mini-side"><div class="mini-count">TODAY <b>01</b> &nbsp; | &nbsp; TOTAL 128</div><div class="mini-profile"><div class="profile-wrap"><div class="profile-circle">${avatar(other?[0,0,0,0,0,0,0]:state.avatar,'',other?p.character:state.character)}</div>${other?'':`<button class="profile-edit" data-action="edit" aria-label="프로필 이미지 수정">✎</button>`}</div><div class="mini-name"><b>${esc(name)}</b></div><p>${other?esc(p.desc):'책과 함께 나를 발견하는 중이에요.'}</p><div class="score-summary"><span>숙련도</span><strong>${other?p.score:state.points} / ${other?p.score:state.totalEarned} P</strong></div><button class="friend-jump text-btn" data-action="friend-jump">일촌 보기 ↓</button>${other?`<button class="primary full" data-action="duel-open">아레나 매칭하기</button>`:''}</div><div class="recent-reading"><b>최근 읽은 책</b>${recent.length?recent.map(b=>`<button data-action="book" data-id="${b.id}">${esc(b.title)}</button>`).join(''):'<small>아직 담은 책이 없어요.</small>'}</div>${friendWave(other,p)}</aside><section class="mini-content"><div class="mini-heading"><div><h2>${esc(name)}의 미니홈피</h2></div>${close()}</div><div class="mini-tabs">${[['home','홈'],['shelf','내 책장'],['shop','꾸미기'],['guestbook','방문록']].map(([id,label])=>`<button data-action="tab" data-tab="${id}" class="${ui.tab===id?'active':''}">${label}</button>`).join('')}</div><div class="mini-scroll">${ui.tab==='home'?`${roomView(other)}<div class="section-head"><div><div class="eyebrow">PICKED FOR YOU</div><h3>${other?'이 독자':'나'}를 위한 도서</h3></div><small>캐릭터 취향을 바탕으로 추천해요</small></div><div class="carousel">${recommended().map(bookCard).join('')}</div><div class="section-head people-head"><div><div class="eyebrow">READERS LIKE YOU</div><h3>취향이 닮은 독자들</h3></div></div><div class="carousel people">${people.map(personCard).join('')}</div>`:ui.tab==='shelf'?shelf(other):ui.tab==='shop'?inventoryView(other):ui.tab==='guestbook'?guestbookView(other):recordsView(other)}</div></section></div>`}


// Representative colors sampled from each linked cover; the final grayscale cover uses neutral ink.
const coverColors=['#b090b0','#503010','#d0b010','#303050','#d0d0f0','#307070','#701010','#d0d0d0'];
books.forEach((book,i)=>{book.cardColor=coverColors[i];const c=book.cardColor;book.cardInk=(parseInt(c.slice(1,3),16)*.299+parseInt(c.slice(3,5),16)*.587+parseInt(c.slice(5,7),16)*.114)>150?'#24161a':'#fffaf5'});
extraBooks.forEach(book=>{const c=book.cardColor;book.cardInk=(parseInt(c.slice(1,3),16)*.299+parseInt(c.slice(3,5),16)*.587+parseInt(c.slice(5,7),16)*.114)>150?'#24161a':'#fffaf5';books.push(book)});
function recommended(){return recommendationIds.map(id=>books.find(b=>b.id===id)).filter(Boolean).slice(0,6)}
function personCard(p){return `<button class="person-card" data-action="person" data-id="${p.id}"><div class="person-pic" style="--person:${p.color}">${avatar([0,0,0,0,0,0,0],'',p.character)}</div><div><b>${esc(p.name)}</b><p>${esc(p.desc)}</p><small>${esc(p.tags)}</small></div></button>`}
function shelf(other){let entries=other?books.slice(0,3).map(b=>[b.id,{score:30}]):Object.entries(state.shelf);let groups=cats.map(cat=>({cat,entries:entries.filter(([id])=>books.find(b=>b.id==id)?.cat===cat)})).filter(g=>g.entries.length);return `<div class="section-head"><div><h3>${other?'이 독자':'나'}의 책장</h3></div>${other?'':`<button class="text-btn" data-action="hide">숙련도 ${state.hidden?'보이기':'숨기기'}</button>`}</div>${groups.length?groups.map(group=>`<section class="shelf-category"><h4>${group.cat}</h4><div class="carousel">${group.entries.map(([id,e])=>{let b=books.find(x=>x.id==id);return `<div class="shelf-card">${bookCard(b)}<div class="shelf-score">${state.hidden&&!other?'숙련도 숨김':`숙련도 ${e.score} P`}</div>${other?'':`<button class="text-btn" data-action="visibility-book" data-id="${id}">숙련도 ${e.publicScore?'공개':'비공개'}</button>`}</div>`}).join('')}</div></section>`).join(''):'<div class="empty">책장이 비어 있어요.<br>마음에 드는 책을 관심 도서로 담아 보세요.<br><button class="outline" data-action="categories">도서 둘러보기 →</button></div>'}${other?'':`<button class="outline" data-action="tab" data-tab="records">독서 기록 보기</button>`}`}

function shop(){let items=[['리본 장식',40,'hat-beret.svg'],['별 장식',60,'hat-crown.svg'],['꽃 장식',80,'hat-scholar.svg'],['실물 도서 교환',200,null]];return `<div class="shop-intro">사용 가능한 숙련도 <b>${state.points} P</b><small>실물 도서 교환은 결제·배송이 없는 예시입니다.</small></div><div class="shop-grid">${items.map(([n,c,file],i)=>`<div class="shop-item"><div>${file?`<img src="/assets/character-pixel/${file}" alt="">`:'책'}</div><b>${n}</b><span>${c} P</span><button class="outline" data-action="buy" data-i="${i}">${state.items.includes(i)?'보유 중':`${c} P로 구매`}</button></div>`).join('')}</div>`}
function eventPanel(){return `<div class="event-overlay"><aside class="event-panel">${close()}<div class="eyebrow">PARTNERSHIP EVENT · 예시</div><h2>이야기가 만나는<br>특별한 순간</h2><p>출판사와 공공기관이 함께하는 독서 이벤트를 만나 보세요.</p><div class="event-image"></div><div class="event-entry"><small>출판사 제휴 · 예시</small><h3>고전의 첫 문장 수집전</h3><p>마음을 움직인 문장을 함께 나누는 시간.</p></div><div class="event-entry"><small>공공기관 제휴 · 예시</small><h3>우리 동네 독서 산책</h3><p>도서관에서 만나는 새로운 독서 친구.</p></div><small>실제 진행 중인 행사가 아닌 화면 예시입니다.</small></aside></div>`}
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
function award(n){state.points+=n;state.totalEarned+=n}
function completeMission(type,points){let key=today()+':'+type;if(state.missions[key]){alert('오늘 이미 완료한 미션이에요.');return}state.missions[key]=true;award(points);save()}
const wikiLink=term=>`<button class="wiki-link" data-action="wiki" data-term="${esc(term)}">#${esc(term)}</button>`;
function linkTags(text){return esc(text).replace(/#([가-힣A-Za-z0-9_]+)/g,(full,term)=>state.wiki[term]?wikiLink(term):full)}
function recordsView(other){if(other)return '<div class="empty">이 독자가 공개한 기록이 아직 없어요.</div>';return `<button class="back records-back" data-action="tab" data-tab="shelf">← 내 책장으로 돌아가기</button><div class="section-head"><div><div class="eyebrow">MY READING NOTES</div><h3>나의 독서 기록</h3></div></div><p class="hint">독후감이나 감상평을 남기면 예시 숙련도 15 P를 받아요. 공개 설정은 예시로 저장되며 실제 다른 사용자에게 공유되지는 않아요.</p><div class="record-form"><label>도서<select id="record-book">${books.map(b=>`<option value="${b.id}">${b.title}</option>`).join('')}</select></label><label>기록 종류<select id="record-type"><option>감상평</option><option>독후감</option></select></label><label>내용<textarea id="record-text" maxlength="2000" placeholder="읽으며 느낀 것을 자유롭게 남겨 주세요"></textarea></label><button class="primary" data-action="record">기록 저장 +15 P</button></div><div class="record-list">${state.records.length?state.records.map(r=>`<article class="discussion"><b>${esc(r.type)} · ${esc(books.find(b=>b.id===r.book)?.title||'도서')}</b><small> ${esc(r.date)}</small><p>${esc(r.text)}</p><button class="text-btn" data-action="visibility-record" data-id="${esc(r.id)}">기록 ${r.isPublic?'공개':'비공개'}</button>${r.image?`<img class="evidence-image" src="${r.image}" alt="첨부한 인증 사진">`:''}</article>`).join(''):'<p class="hint">아직 저장한 기록이 없어요.</p>'}</div>`}
function deskView(){return `<div class="standard-modal desk-modal"><div class="modal-head"><div><div class="eyebrow">INFORMATION DESK</div><h2>안내 데스크</h2><p>오늘의 미션과 이벤트를 한곳에서 만나 보세요.</p></div>${close()}</div><div class="desk-options"><button data-action="missions"><b>오늘의 미션</b><span>출석하고 독서 활동을 기록해요</span><span aria-hidden="true">→</span></button><button data-action="event"><b>이벤트</b><span>독자들과 함께하는 소식을 확인해요</span><span aria-hidden="true">→</span></button></div></div>`}
function missionsView(){let done=type=>Boolean(state.missions[today()+':'+type]);return `<div class="standard-modal"><div class="modal-head"><div><div class="eyebrow">YOUR DAILY READING</div><h2>오늘의 미션</h2><p>작은 습관을 쌓아 이야기에 한 걸음 더 가까이.</p></div>${close()}</div><p class="notice">점수와 인증 기준은 조정할 수 있는 프로토타입 예시예요. 사진은 이 기기에만 저장하며 자동 판독이나 관리자 심사는 하지 않아요.</p><div class="mission-list"><section><div><b>오늘의 출석</b><p>매일 한 번, 책과 만나는 약속</p></div><button class="outline" data-action="checkin" ${done('checkin')?'disabled':''}>${done('checkin')?'완료':'출석 +5 P'}</button></section><section><div><b>책 제목 맞히기</b><p>헤르만 헤세가 쓴 싱클레어의 성장 이야기는?</p><input id="quiz-answer" placeholder="책 제목" aria-label="책 제목 답변"></div><button class="outline" data-action="quiz" ${done('quiz')?'disabled':''}>${done('quiz')?'완료':'정답 확인 +10 P'}</button></section></div><div class="section-head"><div><div class="eyebrow">RECORD YOUR MOMENT</div><h3>독서 활동 인증</h3></div></div><div class="record-form"><label>인증 종류<select id="cert-type"><option value="event">행사 참여 · 50 P</option><option value="sentence">책 속 문장 사진 · 40 P</option><option value="purchase">도서 구매 · 50 P</option></select></label><label>도서<select id="cert-book">${books.map(b=>`<option value="${b.id}">${b.title}</option>`).join('')}</select></label><label>인증 사진<input id="cert-file" type="file" accept="image/*"></label><label>메모<input id="cert-note" maxlength="200" placeholder="어떤 순간이었나요? (선택)"></label><button class="primary" data-action="certify">사진 인증하고 점수 받기</button><small class="hint">종류별 하루 1회 · 인증 사진은 크기를 줄여 저장합니다.</small></div></div>`}
async function certify(){const type=document.querySelector('#cert-type').value,id=+document.querySelector('#cert-book').value,file=document.querySelector('#cert-file').files[0],note=document.querySelector('#cert-note').value.trim(),key=today()+':cert-'+type;if(state.missions[key]){alert('이 종류의 인증은 오늘 이미 완료했어요.');return}if(!file||!file.type.startsWith('image/')){alert('인증할 이미지 파일을 선택해 주세요.');return}if(file.size>15*1024*1024){alert('15MB 이하 이미지를 선택해 주세요.');return}try{let image=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,900/Math.max(image.width,image.height));canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);image.close();let data=canvas.toDataURL('image/jpeg',0.65);if(data.length>300000){alert('사진을 저장하기 어려워요. 작은 사진을 선택해 주세요.');return}let points={event:50,sentence:40,purchase:50}[type],label={event:'행사 참여 인증',sentence:'문장 사진 인증',purchase:'도서 구매 인증'}[type];state.records.unshift({id:crypto.randomUUID(),book:id,type:label,text:note,date:today(),image:data});state.missions[key]=true;state.shelf[id] ||= {score:0};state.shelf[id].score+=points;award(points);if(await save())alert(`${label}이 저장되었어요. +${points} P`);if(document.querySelector('.mission-overlay'))refreshMissionOverlay();else render()}catch{alert('사진을 열지 못했어요. 다른 이미지 파일을 선택해 주세요.')}}
function renderThread(posts,parent=null,depth=0){return posts.filter(p=>p.parent===parent).map(p=>`<div class="thread ${depth?'thread-reply':''}"><div class="discussion"><b>${esc(p.author)} <small>· ${p.type==='review'?'한 줄평':'댓글'}</small></b><p>${linkTags(p.text)}</p><button class="text-btn" data-action="like" data-id="${esc(p.id)}">${p.liked?'♥':'♡'} ${p.likes}</button> <button class="text-btn" data-action="reply" data-id="${esc(p.id)}">답글</button></div>${renderThread(posts,p.id,depth+1)}</div>`).join('')}
function bookView(b,entry){let posts=state.forums[b.id]||[],reviews=posts.filter(p=>p.type==='review'),top=reviews.reduce((a,p)=>!a||p.likes>a.likes?p:a,null),related=Object.keys(state.wiki).filter(term=>state.wiki[term].books.includes(b.id));return `<div class="standard-modal book-detail"><div class="modal-head"><div><button class="back" data-action="categories">← 도서 둘러보기</button><div class="eyebrow">BOOK FORUM / ${b.cat}</div><h2>${esc(b.title)}</h2><p>${esc(b.author)} · 고전 문학</p></div>${close()}</div><div class="book-hero">${cover(b)}<div class="book-hero-copy"><div class="eyebrow">MOST LOVED LINE &nbsp; ♥ ${top?top.likes:128}</div><blockquote>“${top?linkTags(top.text):esc(b.quote)}”</blockquote><p>${top?esc(top.author)+'님의 한 줄평':'예시 독자의 한 줄평'}</p><small>※ 예시 문장은 원문 인용이 아닙니다.</small><p><a class="cover-source" href="${b.url}" target="_blank" rel="noopener noreferrer">표지 출처: ${b.store}${b.edition?` · ${b.edition}`:''} ↗</a></p><div class="book-actions"><button class="primary" data-action="add" data-id="${b.id}">${entry?'✓ 내 책장에 담김':'♡ 관심 도서로 담기'}</button>${entry?`<button class="outline" data-action="progress" data-id="${b.id}">진도 기록 +10 P</button>`:''}</div></div></div><section class="book-wiki"><div class="eyebrow">ABOUT THIS BOOK</div><h3>책과 관련된 이야기</h3><p>${esc(b.title)}은(는) ${esc(b.cat)}의 주제로 만나볼 수 있는 작품이에요. 아래 키워드로 연결된 다른 책도 살펴보세요.</p><div>${related.map(wikiLink).join(' ')}</div><small>책 설명과 위키 항목은 프로토타입 예시입니다.</small></section><div class="forum-layout"><div><div class="section-head"><div><div class="eyebrow">THE CONVERSATION</div><h3>한 줄평과 대화</h3></div><span>${posts.length}개의 이야기</span></div>${posts.length?renderThread(posts):'<p class="hint">첫 이야기를 남겨 보세요. #성장처럼 위키 단어를 연결할 수 있어요.</p>'}<div class="record-form forum-form">${ui.replyTo?`<div class="notice">답글 작성 중 <button class="text-btn" data-action="reply-cancel">취소</button></div>`:''}<label>종류<select id="forum-type"><option value="comment">댓글</option><option value="review" ${ui.replyTo?'disabled':''}>한 줄평</option></select></label><label>내용<textarea id="forum-text" maxlength="500" placeholder="이 책에 대한 생각과 #위키단어를 남겨 보세요"></textarea></label><button class="primary" data-action="forum-add">${ui.replyTo?'답글 등록':'이야기 등록'} +5 P</button></div></div><aside class="top-reader"><div class="eyebrow">TOP READER · 예시</div><h3>이 책의 빛나는 독자</h3><p>문장수집가 · 480 P</p><button class="outline" data-action="person" data-id="m">미니홈피 방문 ↗</button></aside></div></div>`}
function wikiView(){const item=state.wiki[ui.wiki];if(!item)return '<div class="standard-modal">항목이 없습니다. '+close()+'</div>';return `<div class="standard-modal"><div class="modal-head"><div><button class="back" data-action="book-back">← 도서로 돌아가기</button><div class="eyebrow">READ CARPET WIKI · 예시</div><h2>#${esc(ui.wiki)}</h2><p>${esc(item.description)}</p></div>${close()}</div><div class="section-head"><div><div class="eyebrow">CONNECTED STORIES</div><h3>연결된 도서</h3></div></div><div class="carousel">${item.books.map(id=>books.find(b=>b.id===id)).filter(Boolean).map(bookCard).join('')}</div></div>`}


let arenaToken=0;
function arenaLater(token,delay,fn){setTimeout(()=>{if(ui.modal==='arena-demo'&&token===arenaToken){fn();render()}},matchMedia('(prefers-reduced-motion: reduce)').matches?Math.min(delay,80):delay)}
function startArena(){heldKeys.clear();let closest=Math.min(...people.map(p=>Math.abs(p.score-state.points))),candidates=people.filter(p=>Math.abs(p.score-state.points)<=closest+150),opponent=candidates[Math.floor(Math.random()*candidates.length)];ui.arena={phase:'matching',opponent,selected:[],revealed:0};ui.modal='arena-demo';let token=++arenaToken;render();arenaLater(token,2200,()=>ui.arena.phase='matched');arenaLater(token,4500,()=>ui.arena.phase='pick')}
function playArena(){if(ui.arena.selected.length!==3)return;ui.arena.opponentCards=books.slice(-3).map(b=>b.id);ui.arena.phase='ready';ui.arena.revealed=0;let token=arenaToken;render();arenaLater(token,1600,()=>ui.arena.phase='reveal');[1,2,3].forEach((n)=>arenaLater(token,1800+n*1400,()=>ui.arena.revealed=n));arenaLater(token,7800,()=>ui.arena.phase='result')}
const demoMine=id=>state.shelf[id]?.score ?? (45+(id*13%55));
const demoRival=id=>20+(id*17%61);
function arenaView(){let a=ui.arena,op=a.opponent,phase=a.phase;let intro=phase==='matching'?`<div class="arena-center"><div class="arena-spinner"></div><h2>비슷한 독자를 찾고 있어요</h2><p>숙련도를 기준으로 상대를 매칭하는 중</p></div>`:phase==='matched'?`<div class="arena-center arena-appear"><div class="arena-vs">${avatar()}<b>VS</b>${avatar([2,1,1,3,2,1,1])}</div><h2>매칭 완료!</h2><p>${esc(op.name)}님을 만났어요 · ${op.score} P</p></div>`:phase==='pick'?`<div class="arena-pick"><div class="arena-title"><span>ROUND 1</span><h2>책 카드 세 장을 골라 주세요</h2><p>선택한 순서대로 숙련도를 비교해요. ${a.selected.length} / 3</p></div><div class="arena-picks">${books.map(b=>`<button class="arena-pick-card ${a.selected.includes(b.id)?'selected':''}" data-action="arena-pick" data-id="${b.id}"><img data-book-cover src="${b.image}" alt=""><span><b>${esc(b.title)}</b><small>시연 숙련도 ${demoMine(b.id)} P</small></span>${a.selected.includes(b.id)?`<i>${a.selected.indexOf(b.id)+1}</i>`:''}</button>`).join('')}</div><button class="primary" data-action="arena-play" ${a.selected.length!==3?'disabled':''}>카드 공개하기</button></div>`:(()=>{let mine=0,theirs=0;let rows=a.selected.map((id,i)=>{let b=books.find(x=>x.id===id),opBook=books.find(x=>x.id===a.opponentCards[i]),my=demoMine(id),opScore=demoRival(opBook.id),open=a.revealed>i;mine+=my;theirs+=opScore;return `<div class="arena-row ${open?'revealed':''} ${phase==='reveal'&&a.revealed===i+1?'newly-revealed':''}"><div class="arena-battle-card">${open?`<img data-book-cover src="${b.image}" alt="">`:"<span class=\"arena-card-back\">RC</span>"}<span>${open?esc(b.title):'내 카드'}</span><b>${open?my+' P':'?'}</b></div><span class="arena-row-vs">VS</span><div class="arena-battle-card rival">${open?`<img data-book-cover src="${opBook.image}" alt="">`:"<span class=\"arena-card-back\">RC</span>"}<span>${open?esc(opBook.title):'상대 카드'}</span><b>${open?opScore+' P':'?'}</b></div></div>`}).join('');return `<div class="arena-battle"><div class="arena-title"><span>ROUND 1</span><h2>${phase==='result'?(mine>theirs?'승리!':mine<theirs?'아쉬운 패배':'무승부'):phase==='ready'?'카드를 준비하고 있어요':'카드를 공개합니다'}</h2><p>${phase==='result'?`내 숙련도 ${mine} P · 상대 숙련도 ${theirs} P`:'위에서부터 한 장씩 동시에 공개해요'}</p></div><div class="arena-names"><b>${esc(state.nickname)}</b><b>${esc(op.name)}</b></div>${rows}${phase==='result'?`${mine>theirs&&!a.stolen?`<p class="arena-note">숙련도를 가져올 상대 카드를 골라 주세요.</p><div class="arena-steal-cards">${a.opponentCards.map(id=>{let book=books.find(b=>b.id===id);return `<button data-action="arena-steal" data-id="${id}"><img data-book-cover src="${book.image}" alt=""><span>${esc(book.title)}<small>${demoRival(id)} P</small></span></button>`}).join('')}</div>`:a.stolen?`<p class="arena-transfer">${esc(books.find(b=>b.id===a.stolen.id).title)}에서 ${a.stolen.points} P 획득!</p>`:''}<p class="arena-note">시연 결과로 실제 숙련도는 변하지 않아요.</p><button class="primary" data-action="arena-restart">다시 매칭하기</button>`:''}</div>`})();return `<div class="arena-stage"><div class="arena-shade"></div><div class="arena-top"><span>READ CARPET ARENA · 시연</span>${close()}</div>${intro}</div>`}
function openMissionOverlay(){let prior=ui.modal;ui.modal='missions';let html=modal().replace('class="overlay"','class="overlay mission-overlay"');ui.modal=prior;app.insertAdjacentHTML('beforeend',html);document.querySelector('.mission-overlay .close')?.focus()}
function refreshMissionOverlay(){document.querySelector('.mission-overlay')?.remove();openMissionOverlay()}
function action(a,el){if(a==='friend-jump'){let side=el.closest('.mini-side'),target=side?.querySelector('.friend-wave');if(side&&target)side.scrollTo({top:side.scrollTop+target.getBoundingClientRect().top-side.getBoundingClientRect().top,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return}if(el.closest('.profile-overlay')&&(a==='edit'||a==='equip'||a==='style-category'||a==='style-select')){if(a==='equip'){let i=+el.dataset.i;if(!state.items.includes(i)||i>2)return;state.avatar[6]=[1,3,4][i];save()}if(a==='style-category')ui.inventoryCategory=+el.dataset.slot;if(a==='style-select')chooseStyle(el);ui.tab='shop';document.body.append(scrollButton);let prior=ui.modal;ui.modal='home';document.querySelector('.profile-overlay').outerHTML=modal().replace('class="overlay"','class="overlay profile-overlay"');ui.modal=prior;return}if(a==='mission-overlay'){openMissionOverlay();return}if(el.closest('.mission-overlay')){if(a==='close'){document.querySelector('.mission-overlay').remove();return}if(a==='checkin'){completeMission('checkin',5);refreshMissionOverlay();return}if(a==='quiz'){if(document.querySelector('.mission-overlay #quiz-answer').value.trim()!=='데미안'){alert('다시 생각해 보세요. 힌트: 헤르만 헤세의 작품이에요.');return}completeMission('quiz',10);refreshMissionOverlay();return}if(a==='certify'){certify();return}}if(el.closest('.profile-overlay')){if(a==='guestbook-add'){const input=el.closest('.profile-overlay').querySelector('.guestbook-input');let text=input.value.trim();if(!text){input.focus();return}(state.guestbook.mine ||= []).unshift({author:state.nickname,text,date:today()});save();let prior=ui.modal;ui.modal='home';document.querySelector('.profile-overlay').outerHTML=modal().replace('class=\"overlay\"','class=\"overlay profile-overlay\"');ui.modal=prior;return}if(a==='record'){let panel=el.closest('.profile-overlay'),text=panel.querySelector('#record-text').value.trim(),id=+panel.querySelector('#record-book').value,type=panel.querySelector('#record-type').value;if(!text){alert('독서 기록을 적어 주세요.');return}state.records.unshift({id:crypto.randomUUID(),book:id,type,text,date:today()});state.shelf[id] ||= {score:0};state.shelf[id].score+=15;award(15);save();let prior=ui.modal;ui.modal='home';document.querySelector('.profile-overlay').outerHTML=modal().replace('class=\"overlay\"','class=\"overlay profile-overlay\"');ui.modal=prior;return}if(a==='close'){closeProfile();return}if(a==='tab'){scrollButton.hidden=true;let prior=ui.modal;ui.modal='home';ui.tab=el.dataset.tab;document.querySelector('.profile-overlay').outerHTML=modal().replace('class=\"overlay\"','class=\"overlay profile-overlay\"');ui.modal=prior;return}document.querySelector('.profile-overlay')?.remove();ui.modal='home';ui.screen='world'}if(el.dataset.nav){if(a==='profile'){openProfile();return}ui.event=false;ui.screen='world';if(a==='square'){ui.modal=null;render();return}}switch(a){case'replay-onboarding':heldKeys.clear();ui.event=false;ui.modal=null;ui.replaying=true;ui.nickname=state.nickname;ui.screen='welcome';break;case'replay-exit':ui.replaying=false;ui.screen='world';ui.modal=null;break;case'start':{let n=document.querySelector('#nick').value.trim();if(!n){document.querySelector('#nick').focus();return}ui.nickname=n;openQuiz('welcome');break}case'arena-people':case'arena-demo':startArena();return;case'friend-request':state.friendRequests[ui.person]=true;save();break;case'guestbook-add':{const input=document.querySelector('.guestbook-input');let v=input.value.trim();if(!v){input.focus();return}let id=ui.modal==='person'?ui.person:'mine';(state.guestbook[id] ||= []).unshift({author:state.nickname,text:v,date:today()});save();break}case'option':ui.editor[+el.dataset.i]=+el.dataset.j;break;case'finish':{let nicknameInput=document.querySelector('#edit-nick');if(nicknameInput){let n=nicknameInput.value.trim();if(!n){nicknameInput.focus();return}ui.nickname=n}ui.replaying=false;state.nickname=ui.nickname;state.character=ui.character;state.avatar=[...ui.editor];ui.screen='world';ui.modal='home';ui.tab='home';save();fetch('/api/recommend?avatar='+state.avatar.join(',')).then(r=>r.json()).then(ids=>{recommendationIds=ids;render()});break}case'edit':ui.modal='home';ui.tab='shop';ui.screen='world';break;case'style-category':ui.inventoryCategory=+el.dataset.slot;break;case'style-select':chooseStyle(el);break;case'equip':{let i=+el.dataset.i;if(state.items.includes(i)&&i<3){state.avatar[6]=[1,3,4][i];save()}break}case'quiz-begin':ui.quiz.step=0;break;
case'quiz-answer':{let q=ui.quiz;q.choices[q.step]=+el.dataset.opt;q.step++;if(q.step>=questions.length){let ranked=rankCharacters(q.choices);ui.match={ranked,selected:ranked[0].id};ui.screen='result'}break}
case'quiz-back':ui.quiz.step=Math.max(-1,ui.quiz.step-1);break;
case'quiz-close':ui.screen=ui.quizReturn==='create'&&hasSprite(ui.character)?'create':state.nickname?'world':'welcome';ui.quiz=null;ui.match=null;break;
case'quiz-restart':openQuiz(ui.screen==='create'?'create':ui.quizReturn);ui.quiz.step=0;break;
case'match-pick':ui.match.selected=el.dataset.id;break;
case'match-confirm':{let id=ui.match.selected;if(id!==ui.character||!ui.editor.length)ui.editor=[0,0,0,0,0,0,state.avatar?.[6]||0];ui.character=id;ui.quiz=null;ui.match=null;ui.screen='create';break}case'home':ui.modal='home';ui.tab='home';break;case'person':ui.person=el.dataset.id;state.visitHistory=[ui.person,...state.visitHistory.filter(id=>id!==ui.person)];save();ui.modal='person';ui.tab='home';break;case'tab':ui.tab=el.dataset.tab;break;case'close':if(ui.event)ui.event=false;else ui.modal=null;break;case'categories':ui.modal='categories';ui.category='전체';ui.search='';ui.catalogLimit=4;break;case'category':ui.modal='categories';ui.category=el.dataset.cat;ui.search='';ui.catalogLimit=4;break;case'filter':ui.category=el.dataset.cat;ui.catalogLimit=4;break;case'book':ui.book=+el.dataset.id;ui.replyTo=null;ui.modal='book';break;case'add':state.shelf[el.dataset.id] ||= {score:0};save();break;case'progress':{let e=state.shelf[el.dataset.id];if(e){e.score+=10;award(10);save()}break}case'hide':state.hidden=!state.hidden;save();break;case'visibility-book':{let entry=state.shelf[el.dataset.id];if(entry){entry.publicScore=!entry.publicScore;save()}break}case'visibility-record':{let entry=state.records.find(r=>r.id===el.dataset.id);if(entry){entry.isPublic=!entry.isPublic;save()}break}case'share':{let text=`${state.nickname}의 Read Carpet 미니홈피 ✦\n좋아하는 책을 한 권씩 채우고 있어요.\n${location.origin}`;navigator.clipboard.writeText(text).then(()=>alert('프로필 소개를 복사했어요. 링크는 서비스 첫 화면으로 연결됩니다.')).catch(()=>prompt('아래 소개를 복사해 주세요.',text));return}case'missions':ui.modal='missions';break;

case'checkin':completeMission('checkin',5);break;
case'quiz':{const answer=document.querySelector('#quiz-answer').value.trim();if(answer!=='데미안'){alert('다시 생각해 보세요. 힌트: 헤르만 헤세의 작품이에요.');return}completeMission('quiz',10);break}
case'certify':certify();return;
case'record':{let text=document.querySelector('#record-text').value.trim(),id=+document.querySelector('#record-book').value,type=document.querySelector('#record-type').value;if(!text){alert('독서 기록을 적어 주세요.');return}state.records.unshift({id:crypto.randomUUID(),book:id,type,text,date:today()});state.shelf[id] ||= {score:0};state.shelf[id].score+=15;award(15);save();break}
case'forum-add':{let input=document.querySelector('#forum-text');let text=input.value.trim();if(!text){input.focus();return}let type=document.querySelector('#forum-type').value;(state.forums[ui.book] ||= []).push({id:crypto.randomUUID(),parent:ui.replyTo,text,type,author:state.nickname,likes:0,liked:false});ui.replyTo=null;state.shelf[ui.book] ||= {score:0};state.shelf[ui.book].score+=5;award(5);save();break}
case'reply':ui.replyTo=el.dataset.id;break;
case'reply-cancel':ui.replyTo=null;break;
case'like':{let post=(state.forums[ui.book]||[]).find(p=>p.id===el.dataset.id);if(post){post.liked=!post.liked;post.likes+=post.liked?1:-1;save()}break}
case'wiki':ui.wiki=el.dataset.term;ui.modal='wiki';break;
case'book-back':ui.modal='book';break;case'shop':ui.modal='shop';break;case'buy':{let i=+el.dataset.i,c=[40,60,80,200][i];if(state.items.includes(i)){if(i<3){state.avatar[6]=[1,3,4][i];save();alert('캐릭터에 적용했어요.')}break}if(state.points<c){alert('숙련도가 부족해요. 책의 진도를 기록해 보세요.');break}state.points-=c;state.items.push(i);if(i<3){state.avatar[6]=[1,3,4][i];ui.editor[6]=state.avatar[6]}save();break}case'theme':ui.theme=ui.theme==='light'?'dark':'light';break;case'event':ui.event=true;break;case'duel-open':startArena();return;case'arena-pick':{let id=+el.dataset.id,sel=ui.arena.selected;if(sel.includes(id))ui.arena.selected=sel.filter(x=>x!==id);else if(sel.length<3)sel.push(id);break}case'arena-play':playArena();return;case'arena-restart':startArena();return;case'arena-steal':{let id=+el.dataset.id,a=ui.arena,mine=a.selected.reduce((sum,n)=>sum+demoMine(n),0),rival=a.opponentCards.reduce((sum,n)=>sum+demoRival(n),0);if(a.phase!=='result'||mine<=rival||a.stolen||!a.opponentCards.includes(id))return;let limit=Math.min(demoRival(id),Math.max(1,Math.ceil((mine-rival)/3)));a.stolen={id,points:1+Math.floor(Math.random()*limit)};break}case'duel-pick':{let id=+el.dataset.id;if(ui.duel.includes(id))ui.duel=ui.duel.filter(x=>x!==id);else if(ui.duel.length<3)ui.duel.push(id);break}case'duel-start':{if(ui.duel.length!==3)return;let rival=state.opponents[ui.person] ||= Object.fromEntries(books.map(b=>[b.id,30]));let mine=ui.duel.reduce((a,id)=>a+(state.shelf[id]?.score||0),0),opponent=ui.duel.reduce((a,id)=>a+rival[id],0),delta=0;if(mine>opponent){let id=ui.duel.find(id=>rival[id]>0);if(id){delta=Math.min(10,rival[id]);rival[id]-=delta;state.shelf[id] ||= {score:0};state.shelf[id].score+=delta;award(delta)}}else if(mine<opponent){let id=ui.duel.find(id=>state.shelf[id]?.score>0);if(id){delta=-Math.min(10,state.shelf[id].score,state.points);state.shelf[id].score+=delta;state.points+=delta;rival[id]-=delta}}ui.result=`${mine>opponent?'승리':mine<opponent?'아쉬운 패배':'무승부'}! ${mine} : ${opponent} · ${delta>0?'+':''}${delta} P`;ui.duel=[];save();break}case'move':move(el.dataset.d);return}render()}
const heldKeys=new Set();let walkFrame=0,lastFrame=0;
function updateWalker(){let canvas=document.querySelector('.library-canvas'),b=mapBounds(canvas);ui.x=Math.max(-b.x,Math.min(b.x,ui.x));ui.y=Math.max(-b.y,Math.min(b.y,ui.y));drawLibrary(canvas,{x:ui.x,y:ui.y})}
let lastZone=null, movementPress=null;
function visitDestination(target){if(!target)return;if(movementPress)movementPress.blockClick=true;heldKeys.clear();if(target==='arena-demo'){startArena();return}if(target==='categories'){ui.category='전체';ui.search='';ui.catalogLimit=4;ui.modal='categories'}else if(target==='bookshelf'||target==='inventory'){ui.modal='home';ui.tab=target==='bookshelf'?'shelf':'shop'}else if(target==='desk')ui.modal='desk';render()}
function step(dx,dy){let canvas=document.querySelector('.library-canvas'),b=mapBounds(canvas);ui.x=Math.max(-b.x,Math.min(b.x,ui.x+dx));ui.y=Math.max(-b.y,Math.min(b.y,ui.y+dy));updateWalker();let rect=canvas.getBoundingClientRect(),zone=libraryObjectAt(rect.width/2,rect.height/2);if(zone!==lastZone){lastZone=zone;if(zone)visitDestination(zone)}}
function move(d){if(ui.modal||ui.event||document.querySelector('.profile-overlay'))return;let [dx,dy]={up:[0,-24],down:[0,24],left:[-24,0],right:[24,0]}[d];step(dx,dy)}
function startWalking(){if(walkFrame)return;lastFrame=performance.now();const tick=now=>{if(!heldKeys.size||ui.modal||ui.event||ui.screen!=='world'||document.querySelector('.profile-overlay')){heldKeys.clear();document.querySelector('.lobby-player')?.classList.remove('is-walking');walkFrame=0;return}let dt=Math.min((now-lastFrame)/1000,.05);lastFrame=now;let dx=Number(heldKeys.has('ArrowRight'))-Number(heldKeys.has('ArrowLeft')),dy=Number(heldKeys.has('ArrowDown'))-Number(heldKeys.has('ArrowUp'));let length=Math.hypot(dx,dy)||1;step(dx/length*180*dt,dy/length*180*dt);document.querySelector('.lobby-player')?.classList.add('is-walking');walkFrame=requestAnimationFrame(tick)};walkFrame=requestAnimationFrame(tick)}
document.addEventListener('error',e=>{if(e.target instanceof HTMLImageElement&&e.target.hasAttribute('data-book-cover'))e.target.hidden=true},true);
document.addEventListener('keyup',e=>heldKeys.delete(e.key));window.addEventListener('blur',()=>heldKeys.clear());window.addEventListener('resize',updateWalker);

app.addEventListener('pointerdown',e=>{const button=e.target.closest('.lobby-controls button');if(!button||ui.modal||ui.event||document.querySelector('.profile-overlay'))return;e.preventDefault();const key={up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'}[button.dataset.d];button.dataset.pointerMotion='1';movementPress={x:e.clientX,y:e.clientY,blockClick:false};button.setPointerCapture(e.pointerId);move(button.dataset.d);heldKeys.add(key);startWalking()});
app.addEventListener('pointerup',e=>{const button=e.target.closest('.lobby-controls button');if(!button)return;heldKeys.delete({up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'}[button.dataset.d]);setTimeout(()=>delete button.dataset.pointerMotion,0)});
app.addEventListener('pointercancel',e=>{movementPress=null;heldKeys.clear();const button=e.target.closest('.lobby-controls button');if(button)delete button.dataset.pointerMotion});

// A movement gesture can replace the button with a modal before its click arrives.
// Consume only the click generated at that same position, never a new tap.
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.lobby-controls button'))movementPress=null},true);
document.addEventListener('pointerup',()=>{let press=movementPress;if(press)setTimeout(()=>{if(movementPress===press)movementPress=null},700)},true);
document.addEventListener('click',e=>{if(movementPress?.blockClick&&e.detail>0&&Math.hypot(e.clientX-movementPress.x,e.clientY-movementPress.y)<24){movementPress=null;e.preventDefault();e.stopImmediatePropagation()}},true);
app.addEventListener('click',e=>{const moving=e.target.closest('.lobby-controls button');if(moving?.dataset.pointerMotion){delete moving.dataset.pointerMotion;return}if(e.target.classList.contains('library-canvas')&&!ui.modal&&!ui.event){let rect=e.target.getBoundingClientRect();let target=libraryObjectAt(e.clientX-rect.left,e.clientY-rect.top);if(target){lastZone=target;visitDestination(target)}return}let el=e.target.closest('[data-action]');if(el)action(el.dataset.action,el);else if(e.target.classList.contains('quiz-overlay'))return;else if(e.target.classList.contains('mission-overlay')){e.target.remove()}else if(e.target.classList.contains('profile-overlay')){closeProfile()}else if(e.target.classList.contains('overlay')){ui.modal=null;render()}else if(e.target.classList.contains('event-overlay')){ui.event=false;render()}});
app.addEventListener('input',e=>{if(e.target.id==='edit-nick')ui.nickname=e.target.value;if(e.target.classList.contains('search')){let pos=e.target.selectionStart;ui.search=e.target.value;ui.catalogLimit=4;render();let input=document.querySelector('.search');input.focus();input.setSelectionRange(pos,pos)}});
document.addEventListener('keydown',e=>{if(['quiz','result'].includes(ui.screen)){if(e.key==='Escape'){action('quiz-close',document.body);return}if(ui.screen==='quiz'&&ui.quiz?.step>=0&&(e.key==='1'||e.key==='2')&&!e.target.closest('input,textarea'))document.querySelectorAll('[data-action=quiz-answer]')[+e.key-1]?.click();return}if(e.key==='Escape'){if(document.querySelector('.mission-overlay')){document.querySelector('.mission-overlay').remove();return}if(document.querySelector('.profile-overlay')){closeProfile();return}if(ui.event)ui.event=false;else ui.modal=null;render();return}if(ui.screen==='world'&&!ui.modal&&!ui.event&&!document.querySelector('.profile-overlay')&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();heldKeys.add(e.key);startWalking()}if(e.key==='Enter'&&e.target.id==='nick')action('start',e.target)});render();


try{if(!sessionStorage.getItem('read-carpet-intro')){sessionStorage.setItem('read-carpet-intro','1');const splash=document.createElement('div');splash.className='intro-splash';splash.setAttribute('aria-hidden','true');splash.innerHTML='<img src="/assets/brand/logo-horizontal.png" alt="">';document.body.append(splash);setTimeout(()=>splash.remove(),1600)}}catch{}
